import React, { useState } from "react";
import axios from "axios";

// Define types for better TypeScript support
interface SimplifiedResult {
  simplified_explanation: string;
  steps: string[];
  analogy: {
    text: string;
    mapping: Array<{ concept: string; analogy: string }>;
  };
  why_explanation: string;
}

interface VerificationResult {
  results: Array<{
    claim: string;
    status: "SUPPORTED" | "CONTRADICTED" | "NOT_SUPPORTED";
    evidence: string;
  }>;
  support_score: number;
}

interface QuizQuestion {
  question: string;
  options: string[];
  answer: string;
}

interface QuizResult {
  questions: QuizQuestion[];
}

interface FullResult {
  simplified: SimplifiedResult;
  verification: VerificationResult;
  quiz: QuizResult;
}

function App() {
  const [text, setText] = useState<string>("");
  const [result, setResult] = useState<FullResult | null>(null);
  const [loading, setLoading] = useState<boolean>(false);

  const processText = async () => {
    if (!text.trim()) {
      alert("Please enter some text");
      return;
    }

    setLoading(true);
    try {
      const res = await axios.post("http://localhost:5000/process", { text });
      setResult(res.data);
    } catch (err: any) {
      console.error(err);
      alert("Error: " + (err.response?.data?.error || err.message || "Something went wrong"));
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={{ padding: "30px", maxWidth: "1000px", margin: "0 auto", fontFamily: "Arial, sans-serif" }}>
      <h1 style={{ textAlign: "center", color: "#1e3a8a" }}>🧠 Feynman AI System</h1>

      <textarea
        rows={8}
        style={{ width: "100%", padding: "15px", fontSize: "16px", borderRadius: "8px", border: "1px solid #ccc" }}
        placeholder="Paste your academic text here..."
        value={text}
        onChange={(e) => setText(e.target.value)}
      />

      <br /><br />
      <button
        onClick={processText}
        disabled={loading}
        style={{
          padding: "15px 40px",
          fontSize: "18px",
          background: "#1e3a8a",
          color: "white",
          border: "none",
          borderRadius: "8px",
          cursor: loading ? "not-allowed" : "pointer",
          opacity: loading ? 0.8 : 1,
        }}
      >
        {loading ? "Processing... Please wait" : "🚀 Simplify + Verify + Quiz"}
      </button>

      {result && (
        <div style={{ marginTop: "40px" }}>
          {/* Simplified Explanation */}
          <h2>✅ Simplified Explanation (Feynman Style)</h2>
          <p style={{ fontSize: "18px", lineHeight: "1.6" }}>{result.simplified.simplified_explanation}</p>

          <h3>Steps</h3>
          <ol>
            {result.simplified.steps.map((step, i) => (
              <li key={i} style={{ fontSize: "17px", marginBottom: "8px" }}>{step}</li>
            ))}
          </ol>

          {/* Analogy */}
          <h3>Analogy</h3>
          <p><strong>{result.simplified.analogy.text}</strong></p>
          <ul>
            {result.simplified.analogy.mapping.map((m, i) => (
              <li key={i}><strong>{m.concept}</strong> → {m.analogy}</li>
            ))}
          </ul>

          <h3>Why it works</h3>
          <p>{result.simplified.why_explanation}</p>

          {/* Verification */}
          <h2>🔍 Verification Results</h2>
          <h3>
            Support Score:{" "}
            <span
              style={{
                color: result.verification.support_score >= 80 ? "green" : "red",
                fontWeight: "bold",
              }}
            >
              {result.verification.support_score}%
            </span>
          </h3>

          <table style={{ width: "100%", borderCollapse: "collapse", marginTop: "15px" }}>
            <thead>
              <tr style={{ background: "#f1f5f9" }}>
                <th style={{ padding: "12px", textAlign: "left", border: "1px solid #ddd" }}>Claim</th>
                <th style={{ padding: "12px", textAlign: "left", border: "1px solid #ddd" }}>Status</th>
                <th style={{ padding: "12px", textAlign: "left", border: "1px solid #ddd" }}>Evidence from Original</th>
              </tr>
            </thead>
            <tbody>
              {result.verification.results.map((r, i) => (
                <tr key={i} style={{ borderBottom: "1px solid #ddd" }}>
                  <td style={{ padding: "12px", border: "1px solid #ddd" }}>{r.claim}</td>
                  <td
                    style={{
                      padding: "12px",
                      fontWeight: "bold",
                      border: "1px solid #ddd",
                      color:
                        r.status === "SUPPORTED"
                          ? "green"
                          : r.status === "CONTRADICTED"
                          ? "red"
                          : "orange",
                    }}
                  >
                    {r.status}
                  </td>
                  <td style={{ padding: "12px", fontStyle: "italic", border: "1px solid #ddd" }}>
                    {r.evidence}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>

          {/* Quiz */}
          <h2>📝 Quiz</h2>
          {result.quiz.questions.map((q, i) => (
            <div
              key={i}
              style={{
                marginBottom: "30px",
                background: "#f8fafc",
                padding: "20px",
                borderRadius: "8px",
                border: "1px solid #e2e8f0",
              }}
            >
              <p style={{ fontWeight: "bold", fontSize: "17px" }}>{q.question}</p>
              <ul style={{ marginTop: "10px" }}>
                {q.options.map((opt, j) => (
                  <li key={j} style={{ margin: "8px 0" }}>{opt}</li>
                ))}
              </ul>
              <p style={{ color: "green", fontWeight: "bold", marginTop: "15px" }}>
                Correct Answer: {q.answer}
              </p>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

export default App;
